Si l'identifiant existe déjà, la clé primaire de `utilisateur` fait échouer l'`INSERT` : `$ok` vaut `false` et le message d'erreur s'affiche.

À ajouter dans `mesControles.js` :

```js mesControles.js
function verif2()
{
  if (document.getElementById("idDoc").value == "")
  {
    alert("Sélectionnez un document")
    return false
  }
  let e = document.getElementById("ecriture").checked
  let l = document.getElementById("lecture").checked
  let i = document.getElementById("impression").checked
  if (!e && !l && !i)
  {
    alert("Sélectionnez au moins un droit d'accès")
    return false
  }
  return true
}

function choix1()
{
  if (document.getElementById("ecriture").checked)
    document.getElementById("lecture").checked = true
}

function choix2()
{
  if (!document.getElementById("lecture").checked)
  {
    document.getElementById("ecriture").checked = false
    document.getElementById("impression").checked = false
  }
}

function choix3()
{
  if (document.getElementById("impression").checked)
    document.getElementById("lecture").checked = true
}
```

Les trois fonctions garantissent que **Lecture** est cochée dès qu'un autre droit l'est. Ensuite `verif2` n'a pas à vérifier cette cohérence.

```php droit.php
<?php
include "connexion.php";
$util = mysqli_real_escape_string($con, $_POST["idUtil"]);
$doc = mysqli_real_escape_string($con, $_POST["idDoc"]);
$e = isset($_POST["ecriture"]) ? "O" : "N";
$l = isset($_POST["lecture"]) ? "O" : "N";
$i = isset($_POST["impression"]) ? "O" : "N";

$res = mysqli_query($con, "SELECT * FROM utilisateur WHERE idUtil = '$util'");
if (mysqli_num_rows($res) == 0) {
  echo "Erreur : Utilisateur inexistant";
} else {
  $res = mysqli_query($con, "SELECT * FROM droit WHERE idUtil = '$util' AND idDoc = '$doc'");
  if (mysqli_num_rows($res) > 0) {
    mysqli_query($con, "UPDATE droit SET ecriture = '$e', lecture = '$l', impression = '$i' WHERE idUtil = '$util' AND idDoc = '$doc'");
    echo "Mise à jour des droits d'accès réussie";
  } else {
    mysqli_query($con, "INSERT INTO droit VALUES ('$doc', '$util', '$e', '$l', '$i')");
    echo "Insertion des droits d'accès réussie";
  }
}
?>
```

Les trois cas s'excluent grâce aux `if` / `else` imbriqués. Dans `INSERT INTO droit`, l'ordre des valeurs suit celui de la table : `idDoc` **puis** `idUtil`.

